 assert save_ceremony(f(1),f(31),'opening',rev+1,'allocate',jsonb_build_object('id',f(9902),'quotaId',qf,'registrationId',f(10),'quantity',1))->>'status'='saved';
 assert save_ceremony(f(1),f(31),'opening',rev+2,'allocate',jsonb_build_object('id',f(9903),'quotaId',qa,'registrationId',f(10),'childId',f(40),'quantity',1))->>'status'='duplicate';
 assert save_ceremony(f(1),f(31),'opening',rev+2,'allocate',jsonb_build_object('id',f(9903),'quotaId',qa,'registrationId',f(10),'childId',f(42),'quantity',1))->>'status'='ineligible';
